use strict; use warnings;
sub run {
  my ($w)=@_;
  my $pid=open(my $fh,'-|');
  die unless defined $pid;
  if(!$pid){ open(STDERR,'>','/tmp/perr'); exec('./test15_executable',$w) or exit 127; }
  local $/; my $out=<$fh>; $out='' unless defined $out; close($fh); my $rc=$?;
  open(my $e,'<','/tmp/perr'); local $/; my $err=<$e>; $err='' unless defined $err; close $e;
  return ($out,$err,$rc);
}
sub model {
  my ($w)=@_; my $s="Module::".$w;
  my $pos=rindex($s,":");
  my $start= $pos<0 ? 1 : $pos+2;
  return (undef, sprintf("basic_string::substr: __pos (which is %d) > this->size() (which is %d)",$start,length($s))) if $start>length($s);
  return (substr($s,$start), undef);
}
sub demod_from_out {
  my ($out)=@_;
  # skip 4 newline-terminated lines
  my $i=0; for my $k (1..4){ my $p=index($out,"\n",$i); return undef if $p<0; $i=$p+1; }
  my $rest=substr($out,$i); $rest =~ s/\n\z//; return $rest;
}
my $bad=0; my $n=0;
while(my $w=<STDIN>){ chomp $w; $w =~ s/\\x([0-9a-fA-F]{2})/chr(hex($1))/ge;
  $n++;
  my ($out,$err,$rc)=run($w);
  my ($mval,$merr)=model($w);
  if(defined $merr){
    if($rc==0 || index($err,$merr)<0){ $bad++; printf("MISMATCH(crash) W=[%s] rc=%d err=[%s] expected=[%s]\n", unpack("H*",$w),$rc,$err,$merr); }
  } else {
    my $got=demod_from_out($out);
    if($rc!=0 || !defined $got || $got ne $mval){ $bad++; printf("MISMATCH W=[%s] rc=%d got=[%s] exp=[%s]\n", unpack("H*",$w),$rc, defined $got?unpack("H*",$got):"undef", unpack("H*",$mval)); }
  }
}
printf("checked=%d mismatches=%d\n",$n,$bad);
